/* ============================================================
   i18n 카탈로그 — Toolhub 전 언어 번역 (docs/I18N.md 계약)

   지원 언어 14개 = 전 세계 인구 약 75%의 사용 언어 (L1+L2 화자 기준):
   en 영어 · zh 중국어 · hi 힌디어 · es 스페인어 · ar 아랍어 · fr 프랑스어
   bn 벵골어 · pt 포르투갈어 · ru 러시아어 · ur 우르두어 · id 인도네시아어
   de 독일어 · ja 일본어 · ko 한국어

   ★ 동기화 규칙 (철칙): 새 도구가 허브에 등재될 때마다
     tool.<slug>.name / tool.<slug>.desc (+ 사용법이 있으면 usage.<slug>.*)
     키를 아래 "모든" 언어 블록에 같은 커밋에서 추가한다.
     한 언어라도 빠지면 런칭 게이트 F-4 FAIL.
   ============================================================ */
