    "tool.sleep-cycle-calc.name": "睡眠周期计算器",
    "tool.sleep-cycle-calc.desc": "几点上床才能神清气爽地醒来？几秒钟内获取能完成完整90分钟睡眠周期的就寝时间。",
    "tool.gpa-calc.name": "GPA 计算器",
    "tool.gpa-calc.desc": "输入课程、学分和成绩，立即得到任意制式下的学期与累计 GPA。",
    "tool.fuel-cost-calc.name": "燃油费用计算器",
    "tool.fuel-cost-calc.desc": "这趟行程要花多少油钱？输入距离、油耗和油价，立即得出结果。",
    "tool.random-number-gen.name": "随机数生成器",
    "tool.random-number-gen.desc": "设定区间、选择数量，立刻得到无偏差的随机数 — 或为 Powerball、Mega Millions、EuroMillions 和 Lotto 6/45 获取彩票机选号码。",
    "tool.dice-roller.name": "骰子模拟器",
    "tool.dice-roller.desc": "选一颗骰子点击掷出，或直接输入 2d6+3 这样的骰子表示法。结果公平，全部在浏览器中完成。",
    "tool.coin-flipper.name": "抛硬币",
    "tool.coin-flipper.desc": "正面还是反面？点一下硬币，立刻得到可验证公平的 50/50 结果——批量抛掷查看统计，或给两面命名来做任何决定。",
    "tool.url-encoder.name": "URL 编码/解码器",
    "tool.url-encoder.desc": "即时对 URL 进行百分号编码和解码。可选择 Component 或 Full-URL 范围，切换 form(+) 编码，并完好保留每个字符——中文、韩文、emoji 皆无损。数据不会离开你的浏览器。",
    "tool.hash-gen.name": "哈希生成器",
    "tool.hash-gen.desc": "粘贴文本或拖入文件，立即获得它的 MD5、SHA-1、SHA-256、SHA-384 和 SHA-512 哈希值。粘贴预期值即可校验校验和——全部在浏览器中完成。",
    "tool.color-picker.name": "拾色器与颜色转换器",
    "tool.unix-timestamp-conv.name": "Unix时间戳转换器",
    "tool.fraction-calc.name": "分数计算器",
    "tool.prime-checker.name": "质数检查器",
    "tool.roman-numeral-conv.name": "罗马数字转换器",
    "tool.exchange-rate-conv.name": "汇率换算器",
    "tool.ovulation-calc.name": "排卵计算器",
    "tool.color-picker.desc": "选取一个颜色或粘贴任意代码 — 立即得到 HEX、RGB、HSL、HSV 与 CMYK，一键复制。一切都留在你的浏览器里。",
    "tool.json-formatter.name": "JSON 格式化工具",
    "tool.json-formatter.desc": "粘贴 JSON 即可立即格式化、校验或压缩，并精确显示任何错误的行号和列号。数据不会离开你的浏览器。",
    "tool.base64-conv.name": "Base64 编码/解码器",
    "tool.base64-conv.desc": "即时进行 Base64 编码和解码——文本或图片皆可。完整支持 UTF-8（中文、韩文、emoji、CJK），提供 URL-safe 选项，所有处理都在浏览器中完成。",
    "tool.uuid-gen.name": "UUID 生成器",
    "tool.uuid-gen.desc": "点击生成即可获得一个全新的 RFC 4122 UUID。一次最多批量生成 500 个并全部复制。",
    "tool.child-height-predictor.name": "儿童身高预测器",
    "tool.child-height-predictor.desc": "孩子长大能有多高？根据爸爸妈妈的身高，几秒钟估算成年身高。",
    "tool.speed-conv.name": "速度单位换算器",
    "tool.speed-conv.desc": "只输入一次数字 — 立即看到全部速度单位。",
    "tool.case-converter.name": "大小写转换器",
    "tool.case-converter.desc": "粘贴文本，一次获得所有大小写格式——UPPERCASE、小写、标题、camelCase、snake_case 等。单击任意卡片即可复制。",
    "tool.blood-alcohol-calc.name": "血液酒精浓度计算器（BAC）— 魏德马克公式估算",
    "tool.blood-alcohol-calc.desc": "输入你喝的酒，查看估算的血液酒精浓度——仅供学习参考，绝不是可以开车的信号。",
    "tool.data-size-conv.name": "数据大小换算器",
    "tool.data-size-conv.desc": "只输入一次数字 — 立即在每个数据单位中查看，十进制与二进制并排。",
    "tool.ideal-weight-calc.name": "理想体重计算器",
    "tool.ideal-weight-calc.desc": "理想体重不是一个数字——四个权威公式加上健康BMI范围,一屏对比。",
    "tool.water-intake-calc.name": "喝水量计算器",
    "tool.water-intake-calc.desc": "只需一个数字,看看今天该喝多少水——换算成杯数和瓶数。",
    "tool.workday-calc.name": "工作日计算器",
    "tool.workday-calc.desc": "选择两个日期，周末和公共假日会自动为你扣除。",
    "tool.time-zone-conv.name": "时区转换器",
    "tool.time-zone-conv.desc": "选一个时间和几个城市，时差和夏令时都交给我们。",
    "tool.area-conv.name": "面积单位换算器",
    "tool.area-conv.desc": "只输入一次数字 — 立即换算为每一种面积单位。",
    "tool.volume-conv.name": "体积单位换算器",
    "tool.volume-conv.desc": "只输入一次数字 — 立即看到全部体积单位。",
    "tool.tip-calc.name": "小费计算器",
    "tool.tip-calc.desc": "该给多少小费？输入账单金额，小费和每人分摊会立即显示。",
    "tool.split-bill-calc.name": "AA 分账计算器",
    "tool.split-bill-calc.desc": "总额除以人数，小费和取整都帮你算好。把每人份额复制到群聊。",
    "tool.calorie-calc.name": "卡路里消耗计算器",
    "tool.calorie-calc.desc": "刚才那组运动消耗了多少卡路里？三项输入，三秒出结果。",
    "tool.word-counter.name": "字数统计",
    "tool.word-counter.desc": "粘贴文本，即时获得统计——单词、字符、句子、段落，以及阅读和朗读时间。",
    "tool.weight-conv.name": "重量单位换算器",
