    "tool.unit-price.desc": "العبوة الكبيرة أم الصغيرة — اعرف الأرخص فعلاً في ثوانٍ",
    "tool.sleep-cycle-calc.name": "حاسبة دورات النوم",
    "tool.sleep-cycle-calc.desc": "متى يجب أن تنام لتستيقظ منتعشًا؟ احصل خلال ثوانٍ على أوقات نوم تُكمل دورات نوم كاملة مدتها 90 دقيقة.",
    "tool.gpa-calc.name": "حاسبة المعدل التراكمي GPA",
    "tool.gpa-calc.desc": "أضف موادك وساعاتها ودرجاتها — واحصل فورًا على معدل الفصل والمعدل التراكمي على أي مقياس.",
    "tool.fuel-cost-calc.name": "حاسبة تكلفة الوقود",
    "tool.fuel-cost-calc.desc": "كم ستكلّف هذه الرحلة من الوقود؟ أدخل المسافة والاستهلاك والسعر لتعرف فورًا.",
    "tool.random-number-gen.name": "مولّد أرقام عشوائية",
    "tool.random-number-gen.desc": "حدّد نطاقًا، واختر العدد، واحصل فورًا على أرقام عشوائية بلا انحياز — أو خذ اختيارات يانصيب سريعة لـ Powerball وMega Millions وEuroMillions وLotto 6/45.",
    "tool.dice-roller.name": "رامي النرد",
    "tool.dice-roller.desc": "اختر نردة وارمِها، أو اكتب ترميز نرد مثل 2d6+3. نتائج عادلة، داخل متصفحك مباشرة.",
    "tool.coin-flipper.name": "رمي العملة",
    "tool.coin-flipper.desc": "صورة أم كتابة؟ انقر على العملة لتحصل فورًا على نتيجة عادلة 50/50 — ارمِ عدة عملات دفعة واحدة لرؤية الإحصائيات، أو سمِّ الوجهين لحسم أي قرار.",
    "tool.url-encoder.name": "مُرمِّز / مُفكِّك ترميز URL",
    "tool.url-encoder.desc": "رمِّز وفُكّ ترميز الروابط فورًا بترميز النسبة المئوية. اختر وضع المكوّن أو الرابط الكامل، بدّل ترميز النموذج (+)، واحتفظ بكل حرف — الكورية والإيموجي وحروف CJK — سليمًا. لا شيء يغادر متصفحك.",
    "tool.hash-gen.name": "مولّد التجزئة",
    "tool.hash-gen.desc": "الصق نصًا أو أفلت ملفًا لتحصل فورًا على تجزئات MD5 وSHA-1 وSHA-256 وSHA-384 وSHA-512. تحقّق من مجموع التحقق بلصق القيمة المتوقعة — كل ذلك داخل متصفحك.",
    "tool.color-picker.name": "منتقي الألوان والمحوّل",
    "tool.unix-timestamp-conv.name": "محول الطابع الزمني يونكس",
    "tool.fraction-calc.name": "آلة حاسبة للكسور",
    "tool.prime-checker.name": "فاحص الأعداد الأولية",
    "tool.roman-numeral-conv.name": "محول الأرقام الرومانية",
    "tool.exchange-rate-conv.name": "محول العملات",
    "tool.ovulation-calc.name": "حاسبة التبويض",
    "tool.color-picker.desc": "اختر لونًا أو الصق أي رمز، لتحصل فورًا على HEX و RGB و HSL و HSV و CMYK، مع نسخ بنقرة واحدة. كل شيء يبقى داخل متصفحك.",
    "tool.json-formatter.name": "منسّق JSON",
    "tool.json-formatter.desc": "الصق JSON لتنسيقه أو التحقق منه أو ضغطه فورًا — مع السطر والعمود الدقيقين لأي خطأ. لا شيء يغادر متصفحك.",
    "tool.base64-conv.name": "مُرمِّز / فاكّ ترميز Base64",
