    "usage.heading": "كيف تستخدم الأدوات",
    "usage.unit-price.title": "حاسبة سعر الوحدة — طريقة الاستخدام",
    "usage.unit-price.body": "تقف في المتجر محتاراً بين عبوة منظّف بوزن 500 غرام وأخرى بوزن 1.2 كيلوغرام؟ أدخل سعر كل منتج وحجمه، وستحوّل الحاسبة السعرين إلى سعر لكل 100 غرام لتقارن فوراً. وفي العروض مثل «اشترِ اثنين واحصل على الثالث مجاناً» أدخل عدد القطع في العرض ليُحسب السعر الحقيقي على الحجم الكلي. بلا تسجيل وبلا تثبيت — وأرقامك لا تغادر متصفحك أبداً.",
    "usage.char-count.title": "عدّاد الأحرف — طريقة الاستخدام",
    "usage.char-count.body": "تكتب ضمن حدّ معيّن من الأحرف — رسالة تقديم أو مقالاً أو منشوراً أو وصفاً تعريفياً؟ الصق النص لترى فوراً العدد مع المسافات وبدونها، وكم تبقّى لك حتى هدفك. كما يعرض عدد البايتات (UTF-8 وEUC-KR) للأنظمة التي تحدّ بالبايت بدل الأحرف. كل الحسابات تجري داخل متصفحك؛ لا يُرسل شيء إلى أي خادم، فالنصوص الحساسة آمنة تماماً.",
    "others.heading": "المزيد من صنّاع الموقع",
    "others.lede": "خدمات أخرى يديرها الفريق الذي صنع Toolhub.",
    "others.sta.desc": "منصة تحليل اتجاهات التواصل الاجتماعي لصنّاع المحتوى والمؤثرين",
    "others.isitai.name": "Is It AI?‏ (isitai.me)",
    "others.isitai.desc": "تحقّق مجاناً مما إذا كانت صورة أو فيديو من إنتاج الذكاء الاصطناعي",
    "faq.heading": "الأسئلة الشائعة",
    "faq.q1": "ما هو Toolhub؟",
    "faq.a1": "Toolhub مجموعة أدوات مجانية عبر الإنترنت — مثل حاسبة سعر الوحدة — للمهام اليومية. لا شيء يُثبَّت ولا حساب يُنشأ: افتح المتصفح وستعمل الأدوات مباشرة. كل أداة مصمّمة لحلّ مشكلة واحدة بسرعة.",
    "faq.q2": "هل كل الأدوات مجانية؟",
    "faq.a2": "نعم. كل أداة مدرجة في Toolhub مجانية بالكامل — بلا مدفوعات ولا اشتراكات. وإن ظهرت يوماً ميزة مدفوعة فستُوضَّح بجلاء في صفحة الأداة.",
    "faq.q3": "هل تُرسل بياناتي إلى خادم؟",
    "faq.a3": "لا. أدوات Toolhub صفحات ثابتة تماماً: تُعالَج مدخلاتك داخل متصفحك فقط ولا تُنقل أبداً. أما إعدادات الراحة كالمظهر واللغة فتُحفظ في localStorage هذا المتصفح فقط.",
    "faq.q4": "كم مرة تُضاف أدوات جديدة؟",
    "faq.a4": "نطلق أدوات جديدة بوتيرة أداتين إلى ثلاث كل أسبوع، بدءاً من الأفكار الأكثر فائدة. تظهر الأدوات الجديدة في هذه الصفحة فور إطلاقها، فعُد إلينا بين حين وآخر.",
    "footer.privacy": "سياسة الخصوصية",
    "footer.more": "المزيد من الأدوات",
    "footer.credit": "صنعه rayv",
    "footer.coffee": "☕ اشترِ لي قهوة",
    "why.heading": "لماذا Toolhub",
    "why.free.title": "بدون تسجيل، مجاني دائمًا",
    "why.free.body": "كل أداة مجانية تمامًا وتعمل بدون حساب. فقط افتحها وابدأ — بدون تثبيت، بدون اشتراكات، بدون رسوم خفية.",
    "why.private.title": "يعمل في متصفحك",
    "why.private.body": "كل العمل يتم على جهازك أنت. كل ما تكتبه تتم معالجته داخل متصفحك ولا يغادره أبدًا، لذا تبقى بياناتك خاصة.",
    "why.maintained.title": "صيانة أسبوعية",
    "why.maintained.body": "لا يتم إطلاق أي أداة إلا بعد اجتيازها قائمة فحص الجودة، وتتم مراجعة المجموعة بأكملها كل أسبوع لتبقى الحسابات صحيحة والروابط تعمل.",
