    "tool.fuel-economy-conv.name": "Convertisseur de Consommation",
    "tool.fuel-economy-conv.desc": "Convertissez la consommation de carburant entre MPG (US), MPG (UK), L/100km et km/L instantanément — tapez dans n'importe quel champ et le reste se met à jour. Inclut un tableau de valeurs courantes, calculé dans votre navigateur.",
    "tool.gcf-lcm-calc.name": "Calculateur de PGCD et PPCM",
