    "tool.energy-conv.desc": "জুল, kJ, ক্যালোরি, kcal, Wh, kWh, BTU এবং ফুট-পাউন্ডের মধ্যে তাৎক্ষণিক রূপান্তর — kJ থেকে ক্যালোরি ও খাদ্য ক্যালোরির ফাঁদের ব্যাখ্যাসহ।",
