    "tool.fuel-economy-conv.desc": "MPG (US), MPG (UK), L/100km এবং km/L-এর মধ্যে মাইলেজ তাৎক্ষণিক রূপান্তর করুন — যেকোনো বক্সে টাইপ করুন, বাকিগুলো নিজে থেকেই আপডেট হবে। সাধারণ মানের তুলনা সারণি সহ, সব ব্রাউজারেই হিসাব হয়।",
