    "tool.gcf-lcm-calc.desc": "২ থেকে ৬টি পূর্ণসংখ্যার গরিষ্ঠ সাধারণ গুণনীয়ক (GCF/GCD) ও লঘিষ্ঠ সাধারণ গুণিতক (LCM) বের করুন, প্রতিটি হিসাবে মৌলিক উৎপাদকে বিশ্লেষণ ও ইউক্লিডীয় অ্যালগরিদমের ধাপসহ। বিনামূল্যে, আপনার ব্রাউজারেই চলে।",
