    "tool.unit-price.desc": "বড় প্যাক না ছোট প্যাক — কোনটা আসলে সস্তা, সেকেন্ডেই জানুন",
    "tool.sleep-cycle-calc.name": "স্লিপ সাইকেল ক্যালকুলেটর",
    "tool.sleep-cycle-calc.desc": "সতেজ হয়ে জাগতে কখন ঘুমাতে যাবেন? কয়েক সেকেন্ডে এমন ঘুমানোর সময় পান যা সম্পূর্ণ ৯০ মিনিটের ঘুমচক্র শেষ করে।",
