    "tool.random-number-gen.name": "র‍্যান্ডম নম্বর জেনারেটর",
    "tool.random-number-gen.desc": "একটি রেঞ্জ ঠিক করুন, কতগুলো চান বাছুন, আর সঙ্গে সঙ্গে পক্ষপাতহীন র‍্যান্ডম নম্বর পান — কিংবা Powerball, Mega Millions, EuroMillions ও Lotto 6/45-এর জন্য লটারি কুইক পিক নিন।",
    "tool.dice-roller.name": "ডাইস রোলার",
    "tool.dice-roller.desc": "একটি পাশা বেছে রোল করুন — অথবা 2d6+3-এর মতো ডাইস নোটেশন টাইপ করুন। ন্যায্য ফল, আপনার ব্রাউজারেই।",
    "tool.coin-flipper.name": "কয়েন ফ্লিপ",
    "tool.coin-flipper.desc": "হেড না টেল? কয়েনে ট্যাপ করুন আর সঙ্গে সঙ্গে পান নিরপেক্ষ ৫০/৫০ ফল — একসাথে অনেকগুলো ছুঁড়ে পরিসংখ্যান দেখুন, বা দুই দিকের নাম দিয়ে যেকোনো সিদ্ধান্ত নিন।",
    "tool.url-encoder.name": "URL এনকোডার / ডিকোডার",
    "tool.url-encoder.desc": "সঙ্গে সঙ্গে URL পার্সেন্ট-এনকোড ও ডিকোড করুন। Component বা Full-URL মোড বেছে নিন, form (+) এনকোডিং টগল করুন, এবং প্রতিটি অক্ষর — কোরিয়ান, ইমোজি, CJK — অক্ষত রাখুন। কিছুই আপনার ব্রাউজার ছাড়ে না।",
    "tool.hash-gen.name": "হ্যাশ জেনারেটর",
