    "usage.unit-price.body": "দোকানে দাঁড়িয়ে বুঝতে পারছেন না ৫০০ গ্রামের ডিটারজেন্ট সস্তা, নাকি ১.২ কেজিরটা? দুটি পণ্যের দাম ও পরিমাণ লিখুন — ক্যালকুলেটর দুটোকেই প্রতি ১০০ গ্রামের দামে রূপান্তর করে তাৎক্ষণিক তুলনা দেখাবে। 'দুটি কিনলে একটি ফ্রি'-র মতো বান্ডলে বান্ডলের আইটেম সংখ্যা দিলে মোট পরিমাণের ভিত্তিতে সঠিক হিসাব হয়। সাইন-আপ বা ইনস্টল লাগে না — আপনার সংখ্যাগুলো ব্রাউজারের বাইরে যায় না।",
    "usage.char-count.title": "অক্ষর গণনাকারী — ব্যবহারবিধি",
    "usage.char-count.body": "অক্ষরসীমার মধ্যে লিখছেন — কভার লেটার, প্রবন্ধ, সোশ্যাল পোস্ট বা মেটা বিবরণ? টেক্সট পেস্ট করলেই স্পেসসহ ও স্পেস ছাড়া গণনা এবং লক্ষ্যের তুলনায় কতটা বাকি তা সাথে সাথে দেখা যায়। যেসব সিস্টেম বাইট দিয়ে সীমা নির্ধারণ করে, তাদের জন্য UTF-8 ও EUC-KR বাইট সংখ্যাও দেখায়। সব হিসাব ব্রাউজারের ভেতরেই হয়; কিছুই সার্ভারে পাঠানো হয় না, তাই সংবেদনশীল লেখাও নিশ্চিন্তে পেস্ট করুন।",
    "others.heading": "নির্মাতাদের অন্যান্য সেবা",
    "others.lede": "Toolhub-এর নির্মাতা দলের অন্যান্য সেবাও দেখুন।",
    "others.sta.desc": "ক্রিয়েটর ও ইনফ্লুয়েন্সারদের জন্য সোশ্যাল ট্রেন্ড বিশ্লেষণ প্ল্যাটফর্ম",
    "others.isitai.name": "Is It AI? (isitai.me)",
    "others.isitai.desc": "কোনো ছবি বা ভিডিও AI দিয়ে তৈরি কি না — বিনামূল্যে যাচাই করুন",
    "faq.heading": "সচরাচর জিজ্ঞাসা",
    "faq.q1": "Toolhub কী?",
    "faq.a1": "Toolhub হলো ফ্রি অনলাইন টুলের সংগ্রহ — যেমন ইউনিট মূল্য ক্যালকুলেটর — দৈনন্দিন কাজের জন্য। কিছু ইনস্টল করতে হয় না, অ্যাকাউন্টও লাগে না: ব্রাউজার খুললেই চলে। প্রতিটি টুল একটি সমস্যা দ্রুত সমাধানের জন্য তৈরি।",
    "faq.q2": "সব টুল কি ফ্রি?",
    "faq.a2": "হ্যাঁ। Toolhub-এ তালিকাভুক্ত প্রতিটি টুল সম্পূর্ণ ফ্রি — কোনো পেমেন্ট বা সাবস্ক্রিপশন নেই। কখনো কোনো পেইড ফিচার এলে টুলের পাতায় স্পষ্টভাবে জানানো হবে।",
    "faq.q3": "আমার ডেটা কি সার্ভারে পাঠানো হয়?",
    "faq.a3": "না। Toolhub-এর টুলগুলো সম্পূর্ণ স্ট্যাটিক পেজ: আপনার ইনপুট শুধু ব্রাউজারের ভেতরে প্রক্রিয়া হয়, কোথাও পাঠানো হয় না। থিম বা ভাষার মতো সেটিংস শুধু এই ব্রাউজারের localStorage-এ থাকে।",
    "faq.q4": "নতুন টুল কত ঘন ঘন যোগ হয়?",
    "faq.a4": "আমরা সপ্তাহে ২-৩টি নতুন টুল চালু করি, সবচেয়ে দরকারি আইডিয়া থেকে শুরু করে। নতুন টুল চালু হওয়ামাত্র এই পাতায় যুক্ত হয়, তাই মাঝে মাঝে ঘুরে যান।",
    "footer.privacy": "গোপনীয়তা নীতি",
    "footer.more": "আরও টুল",
    "footer.credit": "নির্মাতা: rayv",
    "footer.coffee": "☕ আমাকে এক কাপ কফি খাওয়ান",
    "why.heading": "কেন Toolhub",
    "why.free.title": "সাইন-আপ ছাড়াই, সবসময় বিনামূল্যে",
    "why.free.body": "প্রতিটি টুল সম্পূর্ণ বিনামূল্যে এবং অ্যাকাউন্ট ছাড়াই কাজ করে। শুধু খুলুন এবং শুরু করুন — কোনো ইনস্টল নেই, কোনো সাবস্ক্রিপশন নেই, কোনো লুকানো খরচ নেই।",
    "why.private.title": "আপনার ব্রাউজারে চলে",
    "why.private.body": "সব কাজ আপনার নিজের ডিভাইসেই হয়। আপনি যা টাইপ করেন তা আপনার ব্রাউজারের ভেতরেই প্রক্রিয়া হয় এবং কখনো বাইরে যায় না, তাই আপনার ডেটা ব্যক্তিগত থাকে।",
    "why.maintained.title": "সাপ্তাহিক রক্ষণাবেক্ষণ",
    "why.maintained.body": "প্রতিটি টুল কেবল একটি QA চেকলিস্ট পাস করার পরেই চালু হয়, এবং পুরো সংগ্রহটি প্রতি সপ্তাহে পর্যালোচনা করা হয় যাতে গণনা সঠিক থাকে এবং লিঙ্ক কাজ করে।",
    "footer.about": "সম্পর্কে",
    "footer.contact": "যোগাযোগ",
    "footer.terms": "শর্তাবলী",
