    "tool.loan-calc.name": "Calculadora de empréstimo",
    "tool.loan-calc.desc": "Informe o valor, a taxa de juros e o prazo — sua prestação mensal, os juros totais e a tabela de amortização completa aparecem na hora, com três métodos de pagamento comparados em uma só tela.",
    "tool.savings-calc.name": "Calculadora de poupança",
    "tool.savings-calc.desc": "Quanto você terá se poupar todo mês? Obtenha o valor no vencimento — juros brutos, imposto retido e líquido na mão — em segundos. Funciona em qualquer moeda.",
    "tool.body-fat-calc.name": "Calculadora de gordura corporal",
