    "tool.find-replace-text.desc": "کیس حساس، مکمل لفظ اور ریگیکس آپشنز کے ساتھ متن تلاش اور تبدیل کریں، لاگو کرنے سے پہلے لائیو پیش منظر کے ساتھ۔",
    "tool.fuel-economy-conv.name": "فیول اکانومی کنورٹر",
    "tool.fuel-economy-conv.desc": "MPG (US)، MPG (UK)، L/100km اور km/L کے درمیان مائلیج فوری تبدیل کریں — کسی بھی خانے میں لکھیں، باقی خودکار اپڈیٹ ہوں گے۔ عام اقدار کا موازنہ جدول شامل، سب کچھ براؤزر میں شمار۔",
    "tool.gcf-lcm-calc.name": "GCF اور LCM کیلکولیٹر",
    "tool.gcf-lcm-calc.desc": "2 سے 6 پورے اعداد کا سب سے بڑا مشترک عامل (GCF) اور سب سے چھوٹا مشترک مضاعف (LCM) نکالیں، ہر حساب کے ساتھ بنیادی عوامل میں تجزیہ اور اقلیدسی الگورتھم کے مراحل دیکھیں۔ مفت، آپ کے براؤزر میں ہی چلتا ہے۔",
    "tool.leap-year-checker.name": "لیپ ایئر چیکر",
    "tool.leap-year-checker.desc": "کوئی بھی سال لیپ ایئر ہے یا نہیں چیک کریں، 4/100/400 کا اصول دیکھیں، رینج میں لیپ سالوں کی فہرست پائیں اور اگلا یا پچھلا لیپ سال تلاش کریں۔",
    "tool.military-time-conv.name": "ملٹری ٹائم کنورٹر",
    "tool.military-time-conv.desc": "ملٹری (24 گھنٹے) وقت کو اسٹینڈرڈ 12 گھنٹے AM/PM وقت میں اور واپس تبدیل کریں، لچکدار ان پٹ پارسنگ اور مکمل 24 گھنٹے کے حوالہ جاتی چارٹ کے ساتھ۔ تمام حساب آپ کے براؤزر میں ہوتے ہیں۔",
    "tool.power-conv.name": "پاور کنورٹر",
    "tool.power-conv.desc": "واٹ، کلو واٹ، میگا واٹ، ہارس پاور (hp اور PS)، BTU/h اور فٹ-پاؤنڈ/سیکنڈ کے درمیان پاور فوری تبدیل کریں — سب کچھ آپ کے براؤزر میں۔",
    "tool.pressure-conv.name": "پریشر کنورٹر",
    "tool.pressure-conv.desc": "Pa، kPa، MPa، bar، psi، atm، mmHg اور inHg کے درمیان دباؤ فوری تبدیل کریں — ٹائپ کرتے ہی تمام 8 یونٹس اپڈیٹ ہوتے ہیں، سب کچھ آپ کے براؤزر میں۔",
    "tool.protein-intake-calc.name": "پروٹین انٹیک کیلکولیٹر",
