    "flagship.desc": "تخلیق کاروں اور انفلوئنسرز کے لیے سوشل ٹرینڈ تجزیاتی پلیٹ فارم۔ کی ورڈ تجزیہ، حریف ریڈار اور سگنل آرکائیو — سب ایک جگہ۔",
