    "usage.unit-price.title": "یونٹ قیمت کیلکولیٹر — طریقۂ استعمال",
    "usage.unit-price.body": "دکان میں سمجھ نہیں آ رہا کہ 500 گرام والا ڈٹرجنٹ سستا ہے یا 1.2 کلو والا؟ دونوں مصنوعات کی قیمت اور مقدار درج کریں — کیلکولیٹر دونوں کو فی 100 گرام قیمت میں بدل کر فوراً موازنہ دکھا دیتا ہے۔ 'دو خریدیں، ایک مفت' جیسے بنڈل کے لیے بنڈل میں اشیاء کی تعداد درج کریں تو کل مقدار کے حساب سے درست قیمت نکلتی ہے۔ نہ سائن اپ، نہ انسٹال — آپ کے اعداد براؤزر سے باہر نہیں جاتے۔",
    "usage.char-count.title": "حروف شمار — طریقۂ استعمال",
    "usage.char-count.body": "حروف کی حد کے اندر لکھ رہے ہیں — کور لیٹر، مضمون، سوشل پوسٹ یا میٹا تفصیل؟ متن پیسٹ کرتے ہی خالی جگہوں سمیت اور ان کے بغیر گنتی، اور ہدف کے مقابلے میں کتنی گنجائش باقی ہے، فوراً نظر آ جاتی ہے۔ جو سسٹم بائٹس کے حساب سے حد لگاتے ہیں ان کے لیے UTF-8 اور EUC-KR بائٹ گنتی بھی دکھائی جاتی ہے۔ ساری گنتی براؤزر کے اندر ہوتی ہے؛ کچھ بھی سرور کو نہیں بھیجا جاتا، اس لیے حساس متن بھی بے فکر پیسٹ کریں۔",
    "others.heading": "بنانے والوں کی دیگر خدمات",
