    "others.sta.desc": "تخلیق کاروں اور انفلوئنسرز کے لیے سوشل ٹرینڈ تجزیاتی پلیٹ فارم",
    "others.isitai.name": "Is It AI?‏ (isitai.me)",
    "others.isitai.desc": "مفت جانچیں کہ کوئی تصویر یا ویڈیو AI سے بنی ہے یا نہیں",
    "faq.heading": "اکثر پوچھے جانے والے سوالات",
    "faq.q1": "Toolhub کیا ہے؟",
    "faq.a1": "Toolhub مفت آن لائن ٹولز کا مجموعہ ہے — جیسے یونٹ قیمت کیلکولیٹر — جو روزمرہ کے کاموں میں فوراً کام آتے ہیں۔ کچھ انسٹال کرنے یا اکاؤنٹ بنانے کی ضرورت نہیں: براؤزر کھولیں اور استعمال شروع کریں۔ ہر ٹول ایک مسئلہ تیزی سے حل کرنے کے لیے بنایا گیا ہے۔",
    "faq.q2": "کیا تمام ٹولز مفت ہیں؟",
    "faq.a2": "جی ہاں۔ Toolhub پر درج ہر ٹول مکمل طور پر مفت ہے — نہ ادائیگی، نہ سبسکرپشن۔ اگر کبھی کوئی معاوضہ والی سہولت آئی تو ٹول کے صفحے پر واضح طور پر بتا دیا جائے گا۔",
    "faq.q3": "کیا میرا ڈیٹا سرور کو بھیجا جاتا ہے؟",
    "faq.a3": "نہیں۔ Toolhub کے ٹولز مکمل طور پر سٹیٹک صفحات ہیں: آپ کا اِن پٹ صرف براؤزر کے اندر پروسیس ہوتا ہے اور کہیں منتقل نہیں ہوتا۔ تھیم یا زبان جیسی ترتیبات صرف اسی براؤزر کے localStorage میں رہتی ہیں۔",
    "faq.q4": "نئے ٹولز کتنی بار آتے ہیں؟",
    "faq.a4": "ہم ہر ہفتے 2-3 نئے ٹولز جاری کرتے ہیں، سب سے مفید خیالات سے شروع کر کے۔ نیا ٹول جاری ہوتے ہی اس صفحے کی فہرست میں شامل ہو جاتا ہے، اس لیے وقتاً فوقتاً چکر لگاتے رہیں۔",
    "footer.privacy": "رازداری کی پالیسی",
    "footer.more": "مزید ٹولز",
    "footer.credit": "تخلیق کار: rayv",
    "footer.coffee": "☕ مجھے ایک کافی پلائیں",
    "why.heading": "Toolhub کیوں",
    "why.free.title": "سائن اپ کے بغیر، ہمیشہ مفت",
    "why.free.body": "ہر ٹول مکمل طور پر مفت ہے اور بغیر اکاؤنٹ کے کام کرتا ہے۔ بس کھولیں اور شروع کریں — کوئی انسٹال نہیں، کوئی سبسکرپشن نہیں، کوئی چھپی فیس نہیں۔",
    "why.private.title": "آپ کے براؤزر میں چلتا ہے",
    "why.private.body": "سارا کام آپ کے اپنے آلے پر ہوتا ہے۔ آپ جو کچھ ٹائپ کرتے ہیں وہ آپ کے براؤزر کے اندر ہی پروسیس ہوتا ہے اور کبھی باہر نہیں جاتا، اس لیے آپ کا ڈیٹا نجی رہتا ہے۔",
    "why.maintained.title": "ہفتہ وار دیکھ بھال",
    "why.maintained.body": "ہر ٹول صرف QA چیک لسٹ پاس کرنے کے بعد ہی لانچ ہوتا ہے، اور پورا مجموعہ ہر ہفتے جانچا جاتا ہے تاکہ حساب درست رہیں اور لنکس کام کرتے رہیں۔",
