    "tool.exchange-rate-conv.name": "Währungsrechner",
    "tool.ovulation-calc.name": "Eisprungrechner",
    "tool.color-picker.desc": "Wähle eine Farbe oder füge einen beliebigen Code ein — erhalte sofort HEX, RGB, HSL, HSV und CMYK, mit Kopieren per Klick. Alles bleibt in deinem Browser.",
    "tool.json-formatter.name": "JSON-Formatter",
    "tool.json-formatter.desc": "Fügen Sie JSON ein, um es sofort zu formatieren, zu validieren oder zu minifizieren — mit der genauen Zeile und Spalte jedes Fehlers. Nichts verlässt Ihren Browser.",
    "tool.base64-conv.name": "Base64-Encoder / -Decoder",
    "tool.base64-conv.desc": "Base64 sofort kodieren und dekodieren — Text oder Bilder. Volle UTF-8-Unterstützung (Koreanisch, Emoji, CJK), eine URL-safe-Option, und alles bleibt in Ihrem Browser.",
    "tool.uuid-gen.name": "UUID-Generator",
