    "tool.speed-conv.name": "Geschwindigkeits-Umrechner",
    "tool.speed-conv.desc": "Zahl einmal eingeben — sofort in jeder Geschwindigkeitseinheit sehen.",
    "tool.case-converter.name": "Groß-/Kleinschreibung-Konverter",
    "tool.case-converter.desc": "Fügen Sie Ihren Text ein und erhalten Sie alle Schreibweisen auf einmal — UPPERCASE, Kleinbuchstaben, Titel, camelCase, snake_case und mehr. Klicken Sie auf eine Karte zum Kopieren.",
    "tool.blood-alcohol-calc.name": "Blutalkohol-Rechner (BAC)",
    "tool.blood-alcohol-calc.desc": "Gib deine Getränke ein und sieh einen geschätzten Blutalkohol — ein Lernwert, niemals grünes Licht zum Fahren.",
    "tool.data-size-conv.name": "Datengrößen-Umrechner",
    "tool.data-size-conv.desc": "Zahl einmal eingeben — sofort in jeder Dateneinheit sehen, dezimal und binär nebeneinander.",
    "tool.ideal-weight-calc.name": "Idealgewicht-Rechner",
    "tool.ideal-weight-calc.desc": "Ihr Idealgewicht ist keine einzelne Zahl — vergleichen Sie auf einen Blick vier bewährte Formeln und einen gesunden BMI-Bereich.",
    "tool.water-intake-calc.name": "Wasserbedarf-Rechner",
    "tool.water-intake-calc.desc": "Eine Zahl genügt. Sieh, wie viel Wasser du heute trinken solltest — in Gläsern und Flaschen.",
    "tool.workday-calc.name": "Arbeitstage-Rechner",
    "tool.workday-calc.desc": "Wählen Sie zwei Daten. Wochenenden und Feiertage werden für Sie abgezogen.",
    "tool.time-zone-conv.name": "Zeitzonen-Umrechner",
    "tool.time-zone-conv.desc": "Wähle eine Uhrzeit und ein paar Städte. Die Abstände und die Sommerzeit übernehmen wir für dich.",
    "tool.area-conv.name": "Flächenumrechner",
    "tool.area-conv.desc": "Zahl einmal eingeben — sofort in jeder Flächeneinheit sehen.",
    "tool.volume-conv.name": "Volumenumrechner",
    "tool.volume-conv.desc": "Zahl einmal eingeben — sofort in jeder Volumeneinheit sehen.",
    "tool.tip-calc.name": "Trinkgeld-Rechner",
    "tool.tip-calc.desc": "Wie viel Trinkgeld geben? Rechnungsbetrag eingeben – Trinkgeld und Anteil pro Person erscheinen sofort.",
    "tool.split-bill-calc.name": "Rechnung-teilen-Rechner",
