    "tool.calorie-calc.name": "Kalorienverbrauch-Rechner",
    "tool.calorie-calc.desc": "Wie viele Kalorien hat dieses Workout verbrannt? Drei Eingaben, Antwort in drei Sekunden.",
    "tool.word-counter.name": "Wortzähler",
    "tool.word-counter.desc": "Fügen Sie Ihren Text ein und erhalten Sie sofortige Zählungen: Wörter, Zeichen, Sätze, Absätze plus Lese- und Sprechzeit.",
    "tool.weight-conv.name": "Gewichtsumrechner",
    "tool.weight-conv.desc": "Zahl einmal eingeben — sofort in allen 9 Masseeinheiten sehen.",
    "tool.stopwatch.name": "Online-Stoppuhr",
    "tool.stopwatch.desc": "Leertaste zum Starten und Pausieren, L für Runden. Bleibt auch im Hintergrund-Tab genau.",
    "tool.temp-conv.name": "Temperatur-Umrechner",
    "tool.temp-conv.desc": "In ein beliebiges Feld tippen — die anderen beiden aktualisieren sich sofort.",
    "tool.length-conv.name": "Längenumrechner",
    "tool.length-conv.desc": "Zahl einmal eingeben — sofort in allen 8 Längeneinheiten sehen.",
    "tool.loan-calc.name": "Kreditrechner",
    "tool.loan-calc.desc": "Geben Sie Kreditbetrag, Zinssatz und Laufzeit ein — Ihre monatliche Rate, die Gesamtzinsen und der vollständige Tilgungsplan erscheinen sofort, mit drei Rückzahlungsarten auf einem Bildschirm im Vergleich.",
    "tool.savings-calc.name": "Sparrechner",
    "tool.savings-calc.desc": "Wie viel haben Sie, wenn Sie jeden Monat sparen? Erhalten Sie in Sekunden den Endbetrag — Bruttozinsen, abgezogene Steuer, netto auf der Hand. Funktioniert in jeder Währung.",
    "tool.body-fat-calc.name": "Körperfett-Rechner",
    "tool.body-fat-calc.desc": "Kein InBody-Scan nötig — schätzen Sie Ihren Körperfettanteil mit einem einfachen Maßband.",
    "tool.world-clock.name": "Weltuhr",
    "tool.world-clock.desc": "Füge eine Stadt hinzu und die Uhr läuft los. Die Zeitverschiebung übernehmen wir für dich.",
    "tool.bmr-calc.name": "Grundumsatz-Rechner",
    "tool.bmr-calc.desc": "Kalorien, die Sie schon beim Atmen verbrennen — mit zwei bewährten Formeln genau bestimmen.",
    "tool.countdown-timer.name": "Countdown-Timer",
    "tool.countdown-timer.desc": "Zeit einstellen und auf Start drücken. Es klingelt exakt bei Ablauf — auch im Hintergrund-Tab.",
    "tool.qr-gen.name": "QR-Code-Generator",
    "tool.qr-gen.desc": "Der QR-Code entsteht, während Sie tippen. Keine Registrierung, kein Ablaufdatum — und nichts verlässt Ihren Browser.",
    "tool.date-diff-calc.name": "Datumsdifferenz-Rechner",
    "tool.date-diff-calc.desc": "Einfach zwei Daten wählen — wie viele Tage, Jahre und Monate, sofort sichtbar.",
    "tool.interest-calc.name": "Zinsrechner",
    "tool.interest-calc.desc": "Wie viel Zinsen bringt ein einmalig angelegter Betrag? Einfach oder Zinseszins, nach Steuerabzug — die tatsächliche Auszahlung sofort.",
    "tool.pomodoro-timer.name": "Pomodoro-Timer",
    "tool.pomodoro-timer.desc": "25 Minuten fokussieren, 5 Minuten ausruhen. Den Zyklus übernimmt der Timer.",
    "tool.char-count.name": "Zeichenzähler",
    "tool.char-count.desc": "Text einfügen und sofort Zeichen, Wörter und Bytes zählen",
